import { readFileSync } from "node:fs";

function toMessage(err: unknown): string {
  if (err instanceof Error) {
    return err.message;
  }
  if (typeof err === "string") {
    return err;
  }
  return "unknown error";
}

export function parseNumberList(text: string): number[] {
  const numbers: number[] = [];
  for (const raw of text.split("\n")) {
    const line = raw.trim();
    if (line === "") {
      continue;
    }
    const n = Number(line);
    if (Number.isNaN(n)) {
      throw new Error(`not a number: ${line}`);
    }
    numbers.push(n);
  }
  return numbers;
}

const input = readFileSync(0, "utf8");
try {
  const sum = parseNumberList(input).reduce((total, n) => total + n, 0);
  console.log(`sum: ${sum}`);
} catch (err) {
  console.log(`error: ${toMessage(err)}`);
}

steps.body:
A class for each kind of failure lets a `catch` tell them apart with `instanceof` and read their details as typed fields. Extend `Error`, call `super(message)` first, then assign your own fields, declared as usual, since parameter properties aren't erasable:

```typescript
class ValidationError extends Error {
  override readonly name = "ValidationError";
  readonly field: string;

  constructor(field: string, message: string) {
    super(message);
    this.field = field;
  }
}

const err = new ValidationError("email", "email is required");
console.log(`${err.name} on ${err.field}: ${err.message}`); // ValidationError on email: email is required
```

`name` is already a property of `Error`, so redefining it needs `override` under this course's `noImplicitOverride`. Make it `readonly` with a string literal, and its type is that literal. The name also shows up in stack traces and in `String(err)`, which makes logs easier to read.

To add context while keeping the original error, pass it as the `cause` option: `new Error("could not load config", { cause: err })`. The `cause` property is typed `unknown`, since anything can be thrown.

examples.code:
class NotFoundError extends Error {
  override readonly name = "NotFoundError";
  readonly resource: string;
  readonly id: string;

  constructor(resource: string, id: string) {
    super(`${resource} ${id} not found`);
    this.resource = resource;
    this.id = id;
  }
}

const users = new Map([
  ["u1", "Ada"],
  ["u2", "Grace"],
]);

function findUser(id: string): string {
  const name = users.get(id);
  if (name === undefined) {
    throw new NotFoundError("user", id);
  }
  return name;
}

for (const id of ["u1", "u7"]) {
  try {
    console.log(`found ${findUser(id)}`);
  } catch (err) {
    if (err instanceof NotFoundError) {
      console.log(`404: no ${err.resource} with id ${err.id}`);
      //                     ^? var err: NotFoundError
      console.log(String(err));
    } else {
      throw err;
    }
  }
}

type ErrorCode = "NOT_FOUND" | "CONFLICT" | "INVALID";

class AppError extends Error {
  override readonly name = "AppError";
  readonly code: ErrorCode;

  constructor(code: ErrorCode, message: string) {
    super(message);
    this.code = code;
  }
}

function statusFor(err: AppError): number {
  switch (err.code) {
    case "NOT_FOUND":
      return 404;
    case "CONFLICT":
      return 409;
    case "INVALID":
      return 422;
  }
}

const failures = [
  new AppError("NOT_FOUND", "order o-9 does not exist"),
  new AppError("CONFLICT", "order o-2 is already paid"),
  new AppError("INVALID", "quantity must be at least 1"),
];

for (const err of failures) {
  console.log(`${statusFor(err)} ${err.code}: ${err.message}`);
}

function parseConfig(text: string): unknown {
  try {
    return JSON.parse(text);
  } catch (err) {
    throw new Error("config.json is not valid JSON", { cause: err });
  }
}

function startServer(configText: string): void {
  try {
    parseConfig(configText);
    console.log("server started");
  } catch (err) {
    throw new Error("could not start the server", { cause: err });
  }
}

try {
  startServer("port=8080");
} catch (err) {
  let current: unknown = err;
  let depth = 0;
  while (current instanceof Error) {
    console.log(`${"  ".repeat(depth)}${current.message}`);
    current = current.cause;
    depth++;
  }
}

