practice.solution:
const STOCK = new Map<string, number>([
  ["MUG-01", 5],
  ["TEA-02", 0],
]);

export class UnknownSkuError extends Error {
  override readonly name = "UnknownSkuError";
  readonly sku: string;

  constructor(sku: string) {
    super(`unknown SKU ${sku}`);
    this.sku = sku;
  }
}

export class OutOfStockError extends Error {
  override readonly name = "OutOfStockError";
  readonly sku: string;
  readonly requested: number;
  readonly available: number;

  constructor(sku: string, requested: number, available: number) {
    super(`only ${available} of ${sku} left, ${requested} requested`);
    this.sku = sku;
    this.requested = requested;
    this.available = available;
  }
}

export function reserve(sku: string, qty: number): number {
  const available = STOCK.get(sku);
  if (available === undefined) {
    throw new UnknownSkuError(sku);
  }
  if (qty > available) {
    throw new OutOfStockError(sku, qty, available);
  }
  STOCK.set(sku, available - qty);
  return available - qty;
}

const requests: [sku: string, qty: number][] = [
  ["MUG-01", 2],
  ["MUG-01", 4],
  ["LAMP-09", 1],
  ["TEA-02", 1],
];

for (const [sku, qty] of requests) {
  try {
    const left = reserve(sku, qty);
    console.log(`reserved ${qty} x ${sku}, ${left} left`);
  } catch (err) {
    if (err instanceof OutOfStockError) {
      console.log(`${err.sku}: only ${err.available} left, ${err.requested} requested`);
    } else if (err instanceof UnknownSkuError) {
      console.log(`${err.sku}: no such product`);
    } else {
      throw err;
    }
  }
}

steps.body:
When several promises run at once, several can fail, and each way of combining them reports failure differently:

- `Promise.all` rejects with the first rejection and ignores any later ones.
- `Promise.allSettled` never rejects. Each failure is a result with `status: "rejected"` and a `reason`.
- `Promise.any` rejects only when every promise rejects, with an `AggregateError` whose `errors` array holds every reason, in the order of the input promises.

```typescript
try {
  await Promise.any([Promise.reject(new Error("eu down")), Promise.reject(new Error("us down"))]);
} catch (err) {
  if (err instanceof AggregateError) {
    console.log(`${err.errors.length} failures`); // 2 failures
  }
}
```

`reason` and the items of `errors` are typed `any`, because a promise can reject with anything, so pass each one through a `toMessage(err: unknown)` helper rather than reading `.message` directly.

Never write an empty `catch {}` around work that can fail. It turns a failure into silence, and the bug shows up later as wrong data. Log what failed, or rethrow it.

examples.code:
import { setTimeout as sleep } from "node:timers/promises";

function toMessage(err: unknown): string {
  return err instanceof Error ? err.message : String(err);
}

async function download(mirror: string, ms: number, problem: string): Promise<string> {
  await sleep(ms);
  throw new Error(`${mirror}: ${problem}`);
}

try {
  const from = await Promise.any([
    download("eu", 30, "certificate expired"),
    download("us", 10, "503 Service Unavailable"),
    download("asia", 20, "connection refused"),
  ]);
  console.log(`downloaded from ${from}`);
} catch (err) {
  if (!(err instanceof AggregateError)) {
    throw err;
  }
  console.log(`${err.message}:`);
  for (const reason of err.errors) {
    //                     ^? (property) AggregateError.errors: any[]
    console.log(`- ${toMessage(reason)}`);
  }
}

import { setTimeout as sleep } from "node:timers/promises";

function toMessage(err: unknown): string {
  return err instanceof Error ? err.message : String(err);
}

type Job = { name: string; ms: number; problem?: string };

const jobs: Job[] = [
  { name: "resize images", ms: 30 },
  { name: "send emails", ms: 25, problem: "SMTP server refused the login" },
  { name: "update search", ms: 20 },
  { name: "charge cards", ms: 5, problem: "payment provider timed out" },
];

async function run(job: Job): Promise<string> {
  await sleep(job.ms);
  if (job.problem !== undefined) {
    throw new Error(`${job.name} failed: ${job.problem}`);
  }
  return job.name;
}

const results = await Promise.allSettled(jobs.map(run));
const failed = results.filter((r) => r.status === "rejected");
//    ^? const failed: PromiseRejectedResult[]
console.log(`${results.length - failed.length} of ${results.length} jobs succeeded`);
for (const result of failed) {
  console.log(toMessage(result.reason));
}

import { setTimeout as sleep } from "node:timers/promises";

function toMessage(err: unknown): string {
  return err instanceof Error ? err.message : String(err);
}

async function sendReceipt(email: string): Promise<void> {
  await sleep(5);
  if (!email.includes("@")) {
    throw new Error(`invalid address: ${email}`);
  }
}

const customers = ["ada@example.com", "grace.example.com", "alan@example.com"];

for (const email of customers) {
  try {
    await sendReceipt(email);
  } catch {}
}
console.log(`silent: receipts sent to ${customers.length} customers`);

let sent = 0;
for (const email of customers) {
  try {
    await sendReceipt(email);
    sent++;
  } catch (err) {
    console.log(`logged: ${toMessage(err)}`);
  }
}
console.log(`logged: receipts sent to ${sent} of ${customers.length} customers`);

