import { setTimeout as sleep } from "node:timers/promises";

export type Mirror = { name: string; ms: number; problem?: string };

function toMessage(err: unknown): string {
  return err instanceof Error ? err.message : String(err);
}

async function download(mirror: Mirror): Promise<string> {
  await sleep(mirror.ms);
  if (mirror.problem !== undefined) {
    throw new Error(mirror.problem);
  }
  return mirror.name;
}

const healthy: Mirror[] = [
  { name: "eu-1", ms: 30, problem: "timeout" },
  { name: "us-1", ms: 20 },
  { name: "ap-1", ms: 40 },
];

const broken: Mirror[] = [
  { name: "eu-1", ms: 30, problem: "timeout" },
  { name: "us-1", ms: 10, problem: "503" },
  { name: "ap-1", ms: 20, problem: "refused" },
];

export async function fastestMirror(mirrors: readonly Mirror[]): Promise<string> {
  try {
    return await Promise.any(mirrors.map(download));
  } catch (err) {
    if (err instanceof AggregateError) {
      const reasons = err.errors.map(toMessage).join(", ");
      throw new Error(`all mirrors failed: ${reasons}`, { cause: err });
    }
    throw err;
  }
}

console.log(`downloaded from ${await fastestMirror(healthy)}`);
try {
  console.log(`downloaded from ${await fastestMirror(broken)}`);
} catch (err) {
  console.log(toMessage(err));
}

steps.body:
Some objects need cleanup when you're done with them: a temporary folder, a lock, a database connection. `try`/`finally` works, but it's easy to forget and nests deeper with every resource. A `using` declaration ties the cleanup to the block instead. When the block ends, normally or by a throw, JavaScript calls the value's `[Symbol.dispose]()` method, a method named by the built-in symbol `Symbol.dispose`:

```typescript
class Timer implements Disposable {
  readonly label: string;

  constructor(label: string) {
    this.label = label;
    console.log(`start ${label}`);
  }

  [Symbol.dispose](): void {
    console.log(`stop ${this.label}`);
  }
}

{
  using timer = new Timer("import");
  console.log(`running ${timer.label}`);
}
```

`Disposable` is the built-in interface with that one method, so `implements Disposable` has the checker confirm it, and `using` rejects a value without it. Several `using` declarations are disposed in reverse order: last acquired, first released. When cleanup has to `await`, implement `AsyncDisposable` with an async `[Symbol.asyncDispose]()` method, and declare the value with `await using`. Node 26 runs all of this natively.

examples.code:
class TempDir implements Disposable {
  readonly path: string;

  constructor(path: string) {
    this.path = path;
    console.log(`created ${path}`);
  }

  [Symbol.dispose](): void {
    console.log(`removed ${this.path}`);
  }
}

function exportReport(name: string, fail: boolean): void {
  using dir = new TempDir(`/tmp/${name}`);
  console.log(`writing into ${dir.path}`);
  if (fail) {
    throw new Error("disk full");
  }
  console.log(`${name} exported`);
}

exportReport("march", false);
try {
  exportReport("april", true);
} catch (err) {
  console.log(`caught: ${err instanceof Error ? err.message : String(err)}`);
}

import { setTimeout as sleep } from "node:timers/promises";

class Connection implements AsyncDisposable {
  readonly name: string;

  constructor(name: string) {
    this.name = name;
  }

  static async open(name: string): Promise<Connection> {
    await sleep(5);
    console.log(`opened ${name}`);
    return new Connection(name);
  }

  async query(sql: string): Promise<number> {
    await sleep(5);
    console.log(`${this.name} ran: ${sql}`);
    return 3;
  }

  async [Symbol.asyncDispose](): Promise<void> {
    await sleep(5);
    console.log(`closed ${this.name}`);
  }
}

async function countOrders(): Promise<number> {
  await using db = await Connection.open("orders-db");
  return await db.query("SELECT count(*) FROM orders");
}

console.log(`orders: ${await countOrders()}`);

class Resource implements Disposable {
  readonly name: string;

  constructor(name: string) {
    this.name = name;
    console.log(`open ${name}`);
  }

  [Symbol.dispose](): void {
    console.log(`close ${this.name}`);
  }
}

function importFile(): void {
  using file = new Resource("orders.csv");
  using db = new Resource("database");
  using cleanup = new DisposableStack();
  cleanup.defer(() => console.log("delete temporary rows"));
  console.log(`importing ${file.name} into ${db.name}`);
}

importFile();

