export class Lock implements Disposable {
  readonly name: string;

  constructor(name: string) {
    this.name = name;
    console.log(`acquired ${name}`);
  }

  [Symbol.dispose](): void {
    console.log(`released ${this.name}`);
  }
}

export function transfer(from: string, to: string, fail: boolean): void {
  using fromLock = new Lock(from);
  using toLock = new Lock(to);
  if (fail) {
    throw new Error(`transfer ${fromLock.name} to ${toLock.name} failed`);
  }
  console.log(`moved money from ${from} to ${to}`);
}

transfer("alice", "bob", false);
try {
  transfer("bob", "carol", true);
} catch (err) {
  console.log(`error: ${err instanceof Error ? err.message : String(err)}`);
}
